package com.yeyamo_mobile.api.booking_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="booking_history")public class BookingHistoryEntity{@Id private UUID id;@Column(name="booking_id",nullable=false)private UUID bookingId;@Column(name="actor_id",length=120)private String actorId;@Column(nullable=false,length=80)private String action;@Column(nullable=false,columnDefinition="TEXT")private String details;@Column(name="occurred_at",nullable=false)private Instant occurredAt;protected BookingHistoryEntity(){}public BookingHistoryEntity(UUID booking,String actor,String action,String details){id=UUID.randomUUID();bookingId=booking;actorId=actor;this.action=action;this.details=details;occurredAt=Instant.now();}public UUID getId(){return id;}public String getAction(){return action;}public String getDetails(){return details;}public Instant getOccurredAt(){return occurredAt;}}
